import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadPurwaData(){const e=readFileSync(resolve(__dirname,"../../purwa-falls-explorer/purwa-data.js"),"utf-8");return new Function(e+"\nreturn { PURWA_INFO, HEIGHT_COMPARISONS, SEASONAL_DATA, NEARBY_ATTRACTIONS, GALLERY_IMAGES, REFERENCES };")()}describe("Purwa Falls Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadPurwaData()}),describe("PURWA_INFO metadata",()=>{it("contains correct Purwa Falls location, height, and Tamas River source",()=>{expect(e.PURWA_INFO.id).toBe("purwa-falls"),expect(e.PURWA_INFO.title).toContain("Purwa Falls"),expect(e.PURWA_INFO.waterfallHeight).toContain("70 Meters"),expect(e.PURWA_INFO.riverSource).toContain("Tamas River")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.PURWA_INFO.quickStats)).toBe(!0),expect(e.PURWA_INFO.quickStats.length).toBe(6)})}),describe("HEIGHT_COMPARISONS & SEASONAL_DATA",()=>{it("contains height comparisons and seasonal flow data",()=>{expect(Array.isArray(e.HEIGHT_COMPARISONS)).toBe(!0),expect(e.HEIGHT_COMPARISONS.length).toBeGreaterThanOrEqual(4);const t=e.HEIGHT_COMPARISONS.find(e=>"Purwa Falls"===e.name);expect(t).toBeDefined(),expect(t.heightMeters).toBe(70),expect(Array.isArray(e.SEASONAL_DATA)).toBe(!0),expect(e.SEASONAL_DATA.length).toBeGreaterThanOrEqual(3)})}),describe("NEARBY_ATTRACTIONS & REFERENCES",()=>{it("contains nearby Rewa circuit attractions and references",()=>{expect(Array.isArray(e.NEARBY_ATTRACTIONS)).toBe(!0),expect(e.NEARBY_ATTRACTIONS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});